const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const hash = (value) => {
  let current = 2166136261;

  for (let index = 0; index < value.length; index++) {
    current ^= value.charCodeAt(index);
    current = Math.imul(current, 16777619);
  }

  return (current >>> 0)
    .toString(16)
    .padStart(8, '0');
};

const execution =
  input.execution &&
  typeof input.execution === 'object'
    ? input.execution
    : {};

const workflow =
  input.workflow &&
  typeof input.workflow === 'object'
    ? input.workflow
    : {};

const triggerError =
  execution.error &&
  typeof execution.error === 'object'
    ? execution.error
    : (
        input.error &&
        typeof input.error === 'object'
          ? input.error
          : {}
      );

const triggerMode =
  Object.keys(execution).length > 0 ||
  Object.keys(triggerError).length > 0;

const event_kind = text(
  input.event_kind ||
  (triggerMode ? 'error' : 'audit')
).toLowerCase();

const clinic_id = Number(
  input.clinic_id ?? 0
);
const clinic_name = text(input.clinic_name);

const actor_type = text(
  input.actor_type ||
  (triggerMode ? 'workflow' : 'system')
);

const actor_name = text(
  input.actor_name ||
  workflow.name ||
  'n8n'
);

const workflow_name = text(
  input.workflow_name ||
  workflow.name ||
  execution.workflowName
);

const workflow_id = text(
  input.workflow_id ||
  workflow.id ||
  execution.workflowId
);

const execution_id = text(
  input.execution_id ||
  execution.id
);

const node_name = text(
  input.node_name ||
  execution.lastNodeExecuted ||
  triggerError.node?.name ||
  triggerError.node
);

const error_type = text(
  input.error_type ||
  triggerError.name ||
  triggerError.type ||
  'workflow_error'
);

const error_message = text(
  input.error_message ||
  triggerError.message ||
  execution.errorMessage
);

const stack_trace = text(
  input.stack_trace ||
  triggerError.stack
);

const event_category = text(
  input.event_category ||
  (event_kind === 'error'
    ? 'workflow_error'
    : 'system')
);

const event_action = text(
  input.event_action ||
  (event_kind === 'error'
    ? 'execution_failed'
    : 'event_recorded')
);

const severity = text(
  input.severity ||
  (event_kind === 'error'
    ? 'error'
    : 'info')
).toLowerCase();

const success =
  event_kind === 'error'
    ? false
    : bool(
        input.success === undefined
          ? true
          : input.success
      );

const retryable = bool(input.retryable);
const entity_type = text(input.entity_type);
const entity_id = Number(input.entity_id ?? 0);
const source_channel = text(input.source_channel);
const request_reference =
  text(input.request_reference);

let event_data =
  input.event_data ??
  input.data ??
  {};

let input_snapshot =
  input.input_snapshot ??
  execution.inputData ??
  {};

let error_payload =
  input.error_payload ??
  triggerError ??
  {};

for (const pair of [
  ['event_data', event_data],
  ['input_snapshot', input_snapshot],
  ['error_payload', error_payload],
]) {
  if (typeof pair[1] === 'string') {
    try {
      const parsed = JSON.parse(pair[1] || '{}');

      if (pair[0] === 'event_data') {
        event_data = parsed;
      }

      if (pair[0] === 'input_snapshot') {
        input_snapshot = parsed;
      }

      if (pair[0] === 'error_payload') {
        error_payload = parsed;
      }
    } catch {
      if (pair[0] === 'event_data') {
        event_data = { raw: pair[1] };
      }

      if (pair[0] === 'input_snapshot') {
        input_snapshot = { raw: pair[1] };
      }

      if (pair[0] === 'error_payload') {
        error_payload = { raw: pair[1] };
      }
    }
  }
}

const fingerprintSource = [
  workflow_name,
  node_name,
  error_type,
  error_message.slice(0, 700),
].join('|');

const error_fingerprint =
  text(input.error_fingerprint) ||
  `wferr-${hash(fingerprintSource)}`;

const confirm_record =
  triggerMode
    ? true
    : bool(input.confirm_record);

const errors = [];

if (!['audit', 'error'].includes(event_kind)) {
  errors.push({
    field: 'event_kind',
    message: 'نوع رویداد باید audit یا error باشد.',
  });
}

if (
  clinic_id < 0 ||
  !Number.isInteger(clinic_id)
) {
  errors.push({
    field: 'clinic_id',
    message: 'شناسه کلینیک معتبر نیست.',
  });
}

if (!event_category) {
  errors.push({
    field: 'event_category',
    message: 'دسته رویداد الزامی است.',
  });
}

if (!event_action) {
  errors.push({
    field: 'event_action',
    message: 'عملیات رویداد الزامی است.',
  });
}

if (
  event_kind === 'audit' &&
  !['info', 'warning', 'error', 'critical'].includes(
    severity
  )
) {
  errors.push({
    field: 'severity',
    message: 'شدت Audit معتبر نیست.',
  });
}

if (
  event_kind === 'error' &&
  !['warning', 'error', 'critical'].includes(
    severity
  )
) {
  errors.push({
    field: 'severity',
    message: 'شدت خطا معتبر نیست.',
  });
}

if (
  event_kind === 'error' &&
  !error_message
) {
  errors.push({
    field: 'error_message',
    message: 'متن خطا الزامی است.',
  });
}

if (confirm_record !== true) {
  errors.push({
    field: 'confirm_record',
    message: 'ثبت رویداد باید تأیید شود.',
  });
}

return [{
  json: {
    event_kind,
    clinic_id,
    clinic_name,
    actor_type,
    actor_name,
    event_category,
    event_action,
    entity_type,
    entity_id,
    workflow_name,
    workflow_id,
    execution_id,
    node_name,
    severity,
    success,
    source_channel,
    request_reference,
    event_data_text:
      JSON.stringify(event_data || {}),
    error_fingerprint,
    error_type,
    error_message,
    stack_trace,
    retryable,
    input_snapshot_text:
      JSON.stringify(input_snapshot || {}),
    error_payload_text:
      JSON.stringify(error_payload || {}),
    confirm_record,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
